using System;using System.IO;using System.Linq;
namespace LoopPedal {
static class PerformanceChecks {
 public static void Ui(){try{using(var form=new Pedal(true)){form.Location=new System.Drawing.Point(-20000,-20000);form.Show();form.VerifyPerformanceUi();form.Close();}File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"performance-ui-tests.txt"),"PASS organized Project/Performance menus; automation hooks on actual FX/layer knobs; native live pitch preparation; independent modulator targets and scene controls.");}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"performance-ui-tests.txt"),"FAIL "+ex);Environment.ExitCode=1;}}
 static void Check(bool v,string label){if(!v)throw new Exception(label);}
 sealed class Port:PerformanceTimeline.Port {public float Value=.2f;public long Phase,Cycle=48000;public double Bpm=120;public float get(int t,long a){return Value;}public void set(int t,long a,float v){Value=v;}public long cycle(int b){return Cycle;}public long phase(int b){return Phase;}public double tempo(){return Bpm;}public bool running(){return true;}public float envelope(){return 1;}}
 static void Step(PerformanceTimeline t,Port p,int frames){for(int i=0;i<frames;i+=240){p.Phase+=240;t.tick(p,240);}}
 public static void Run(){try{var mp=new Port{Phase=12345};var manual=new PerformanceTimeline();Check(manual.recordMode==4,"manual default");manual.arm(mp,true);Check(manual.recording&&!manual.armed,"manual starts immediately");manual.touch(mp,100,0,.1f);Step(manual,mp,60000);manual.touch(mp,100,0,.8f);Check(manual.copy().lanes[0].span==60000,"mid-take recovery length");Step(manual,mp,36000);manual.stop();Check(manual.lanes[0].span==96000&&manual.lanes[0].period(mp)==96000,"Start Finish defines exact free length");mp.Cycle=192000;Check(manual.lanes[0].period(mp)==96000,"free remains independent");var p=new Port();var t=new PerformanceTimeline();t.recordMode=0;t.arm(p,false);t.touch(p,100,0,.2f);Step(t,p,24000);t.touch(p,100,0,.8f);Step(t,p,24000);Check(!t.recording&&t.count==1,"record one cycle");p.Phase=12000;t.time=60000;t.lanes[0].touched=-999999;t.tick(p,240);Check(Math.Abs(p.Value-.5)<.02,"curve interpolation");p.Cycle=96000;p.Phase=24000;t.tick(p,240);Check(Math.Abs(p.Value-.5)<.02,"follow length scales");t.lanes[0].mode=3;t.lanes[0].length=2;t.time=24000-240;t.tick(p,240);Check(Math.Abs(p.Value-.5)<.02,"independent length");var copy=t.copy();Check(copy.count==1&&copy.lanes[0].span==48000,"automation persistence");var mod=copy.mods[0];mod.target=102;mod.baseline=.5f;mod.enabled=true;mod.mode=3;mod.rate=1;mod.depth=.4;copy.time=12000-240;copy.tick(p,240);Check(p.Value>.89,"LFO modulation");mod.type=2;for(int i=0;i<80;i++)copy.tick(p,240);Check(p.Value>.89,"envelope modulation");var second=copy.mods[1];second.target=mod.target;second.baseline=.5f;second.enabled=true;second.type=2;second.depth=.1;copy.tick(p,240);Check(p.Value>.99,"combined modulation");copy.clear(p);Check(copy.count==0&&!mod.enabled,"reset");var clock=new MidiClockState();clock.reset(1);clock.receive(250,1000000000);Check(clock.command()==0,"Start waits first clock");for(int i=0;i<49;i++)clock.receive(248,1000000000L+(long)Math.Round(i*60000000000.0/120/24));Check(Math.Abs(clock.bpm-120)<.001&&clock.command()==250,"24PPQN Start");Check(clock.locked(clock.last+100000000)&&!clock.locked(clock.last+1000000000),"clock timeout");clock.receive(252,clock.last);Check(clock.command()==252,"Stop");clock.receive(251,clock.last);clock.receive(248,clock.last+20833333);Check(clock.command()==251,"Continue");clock.reset(2);clock.receive(250,clock.last);Check(clock.command()==0,"no clock feedback");
 var banks=new[]{new Engine(),new Engine()};banks[0].Performance=new PerformanceTimeline();banks[0].Controls=new PerformanceControl(banks);banks[0].Partner=banks[1];banks[1].ClockLeader=banks[0];var audio=Enumerable.Repeat(.1f,9600).ToArray();banks[0].CommitLayer(new Layer{Name="A",Original=audio,Audio=audio});banks[0].LoopFrames=4800;banks[0].Playing=true;banks[0].Frame=1000;banks[0].Scenes.Slots[0]=PerformanceScene.Capture(banks);banks[0].Fx.Delay=.7f;var ready=PerformanceScene.Capture(banks).Prepare();banks[0].Fx.Delay=0;banks[0].Scenes.Pending=ready;banks[0].Scenes.At=3800;banks[0].Scenes.Queued=1;var provider=new LoopProvider(banks[0]);var buffer=new byte[3800*8];provider.Read(buffer,0,buffer.Length);Check(banks[0].Scenes.Active==-1,"scene waits boundary");provider.Read(buffer,0,8);Check(banks[0].Scenes.Active==1&&banks[0].Fx.Delay==.7f,"scene exact callback boundary");var project=PerformanceProject.Capture(banks);ulong stamp=project.Stamp();banks[0].Frame+=900;Check(PerformanceProject.Capture(banks).Stamp()==stamp,"transport stays clean");string path=Path.Combine(Path.GetTempPath(),"Agent-Looper-performance-"+Guid.NewGuid()+".agw");try{project.Save(path);var loaded=PerformanceProject.Load(path);Check(loaded.State.Banks[0].Layers[0].Original.SequenceEqual(audio)&&loaded.Scenes.Slots[0]!=null,"lossless project and scene persistence");}finally{if(File.Exists(path))File.Delete(path);}banks[0].Performance.mods[0].target=100;banks[0].Performance.mods[0].baseline=0;banks[0].Performance.mods[0].enabled=true;stamp=PerformanceProject.Capture(banks).Stamp();banks[0].Fx.Reverb=.8f;Check(PerformanceProject.Capture(banks).Stamp()==stamp,"automation does not dirty");
 var layered=new Engine();layered.CommitLayer(new Layer{Original=audio,Audio=audio});layered.CommitLayer(new Layer{Original=new float[9600],Audio=new float[9600],TakeFeedback=.5,CapturedFrames=4800});Check(layered.Layers[0].DubDecay==.5,"layered overdub feedback");layered.Undo();Check(layered.Layers.Count==1&&layered.Layers[0].DubDecay==1,"feedback undo");var destructive=new Engine{Destructive=true};destructive.CommitLayer(new Layer{Original=audio,Audio=audio});destructive.CommitLayer(new Layer{Original=new float[9600],Audio=new float[9600],TakeFeedback=.5,CapturedFrames=4800});Check(Math.Abs(destructive.Layers[0].Audio[2000]-.05)<.00001,"destructive feedback");
 File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"performance-tests.txt"),"PASS automation recording/interpolation, linked/free lengths, LFO/envelope, persistence, MIDI 24PPQN and transport, boundary scenes, lossless project IO, dirty baselines, feedback and Undo.");}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"performance-tests.txt"),"FAIL "+ex);Environment.ExitCode=1;}}
}
}

namespace LoopPedal {partial class Pedal {
 public void VerifyAutomationFooter(){var footer=Controls.Find("AutomationFooter",true).Single();var buttons=Controls.Find("AutomationButtons",true).Single();var center=PointToClient(buttons.PointToScreen(new System.Drawing.Point(buttons.Width/2,buttons.Height/2)));if(Math.Abs(center.X-ClientSize.Width/2)>1)throw new Exception("Automation buttons not centered: "+center.X+" / "+ClientSize.Width);var info=Controls.Find("AutomationInfo",true).Single();if(info.Bottom>footer.ClientSize.Height)throw new Exception("Footer status clipped: "+info.Bounds+" footer="+footer.Bounds);var bounds=RectangleToClient(footer.RectangleToScreen(footer.ClientRectangle));if(bounds.Bottom>ClientSize.Height||bounds.Bottom<ClientSize.Height-40||!footer.Visible)throw new Exception("Automation footer not at bottom: "+bounds+" client="+ClientSize+" rows="+string.Join(",",((System.Windows.Forms.TableLayoutPanel)footer.Parent).GetRowHeights()));}
 public void VerifyPerformanceUi(){foreach(int width in new[]{1100,1240,1720}){Width=width;System.Windows.Forms.Application.DoEvents();VerifyAutomationFooter();}SetImmersive(true);System.Windows.Forms.Application.DoEvents();VerifyAutomationFooter();SetImmersive(false);System.Windows.Forms.Application.DoEvents();PreviewLayers();System.Windows.Forms.Application.DoEvents();VerifyAutomationFooter();var menu=NewMenu();ProjectItems(menu.Items);if(!menu.Items.Cast<System.Windows.Forms.ToolStripItem>().Any(i=>i.Text=="Save"))throw new Exception("Project Save missing");menu=NewMenu();PerformanceItems(menu.Items);if(menu.Items.Count!=3)throw new Exception("Performance groups");loopers[0].Playing=true;Timeline.arm(Port,false);var fxKnob=MidiKnobs(fxSurface).First(k=>(k.Tag as string)=="FX.0");fxKnob.Commit(300);var pitch=MidiKnobs(this).First(k=>(k.Tag as string)=="A.Layer.0.PITCH");pitch.Commit(30);if(Timeline.count!=2||loopers[0].Layers[0].Stream==null)throw new Exception("Actual knob recording/native preparation");var direct=Controls.Find("AutomationRecord",true).OfType<System.Windows.Forms.Button>().Single();fxMenuPad.PerformClick();if(!direct.Visible)throw new Exception("Automation transport hidden on FX page");VerifyAutomationFooter();direct.PerformClick();if(Timeline.recording||Timeline.armed)throw new Exception("Direct automation Finish");var mod=Timeline.mods[0];mod.target=1002;mod.audio=loopers[0].Layers[0].AudioId;mod.enabled=true;mod.baseline=1;mod.depth=.3;Timeline.tick(Port,240);if(loopers[0].Layers[0].Cutoff<=40)throw new Exception("Layer modulation binding");Timeline.clear(Port);}
}}
